use crate::autograd::Value;use std::{fs::File,io::{Read,Write},path::Path};
pub fn save<P:AsRef<Path>>(path:P,p:&[Value])->std::io::Result<()>{let mut f=File::create(path)?;f.write_all(b"GRS1")?;f.write_all(&(p.len()as u64).to_le_bytes())?;for x in p{let d=x.data();f.write_all(&(d.len()as u64).to_le_bytes())?;for v in d{f.write_all(&v.to_le_bytes())?;}}Ok(())}
pub fn load<P:AsRef<Path>>(path:P,p:&[Value])->std::io::Result<()>{let mut f=File::open(path)?;let mut h=[0u8;4];f.read_exact(&mut h)?;if &h!=b"GRS1"{return Err(std::io::Error::new(std::io::ErrorKind::InvalidData,"bad checkpoint"))}let mut b=[0u8;8];f.read_exact(&mut b)?;let n=u64::from_le_bytes(b)as usize;if n!=p.len(){return Err(std::io::Error::new(std::io::ErrorKind::InvalidData,"parameter count mismatch"))}for x in p{f.read_exact(&mut b)?;let len=u64::from_le_bytes(b)as usize;let mut d=vec![0.;len];for v in &mut d{let mut q=[0u8;4];f.read_exact(&mut q)?;*v=f32::from_le_bytes(q)}x.set_data(d)}Ok(())}
